package com.chesspulseai.service; import com.chesspulseai.enumtype.GameResult; import org.junit.jupiter.api.*; import static org.junit.jupiter.api.Assertions.*; class ProbabilityServiceTest { private final ProbabilityService service=new ProbabilityService(.5); @Test void probabilitiesFormDistribution(){var p=service.from(120,null);assertEquals(100,p.white()+p.black()+p.draw(),.2);assertTrue(p.white()>p.black());}@Test void terminalDrawIsCertain(){var p=service.terminal(GameResult.DRAW);assertEquals(0,p.white());assertEquals(100,p.draw());assertEquals(0,p.black());}@Test void terminalWinIsCertain(){var p=service.terminal(GameResult.WHITE_WIN);assertEquals(100,p.white());assertEquals(0,p.draw());assertEquals(0,p.black());}}
